INSERT INTO `communication_templates` VALUES (1,'2fa_verification','رمز التحقق الثنائي','email','رمز التحقق الثنائي - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>رمز التحقق الثنائي</h2>\n    <p>مرحباً،</p>\n    <p>يرجى استخدام الرمز التالي لإكمال عملية التحقق:</p>\n    <div style=\"font-size: 32px; font-weight: bold; letter-spacing: 5px; color: #4f46e5; text-align: center; margin: 30px 0; padding: 20px; background-color: #f3f4f6; border-radius: 8px;\">\n        {code}\n    </div>\n    <p>هذا الرمز صالح لمدة 10 دقائق. لا تشارك هذا الرمز مع أي شخص.</p>\n</div>','[\"{code}\", \"{app_name}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(2,'email_verification','تفعيل البريد الإلكتروني','email','تفعيل حسابك - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>🔐 تفعيل حسابك</h2>\n    <p>مرحباً {name}،</p>\n    <p>شكراً لتسجيلك في {app_name}!</p>\n    <p>يرجى الضغط على الزر أدناه لتفعيل حسابك:</p>\n    <div style=\"text-align: center; margin: 30px 0;\">\n        <a href=\"{verification_url}\" style=\"background-color: #4f46e5; color: white; padding: 14px 35px; text-decoration: none; border-radius: 8px; display: inline-block; font-weight: bold;\">تفعيل الحساب</a>\n    </div>\n    <p style=\"color: #6b7280; font-size: 14px;\">إذا لم تقم بإنشاء حساب، يمكنك تجاهل هذه الرسالة.</p>\n    <p>فريق {app_name}</p>\n</div>','[\"{name}\", \"{app_name}\", \"{verification_url}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(3,'trial_activation','تفعيل الاشتراك التجريبي','email','تم تفعيل اشتراكك التجريبي - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>🎉 مرحباً بك في {app_name}!</h2>\n    <p>مرحباً {name}،</p>\n    <p>تم تفعيل اشتراكك التجريبي بنجاح!</p>\n    <div style=\"background-color: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 8px; padding: 20px; margin: 20px 0;\">\n        <p><strong>تاريخ البدء:</strong> {start_date}</p>\n        <p><strong>تاريخ الانتهاء:</strong> {end_date}</p>\n        <p><strong>الباقة:</strong> {plan_name}</p>\n    </div>\n    <p>استمتع بجميع الميزات خلال فترة التجربة المجانية!</p>\n    <p>فريق {app_name}</p>\n</div>','[\"{name}\", \"{app_name}\", \"{start_date}\", \"{end_date}\", \"{plan_name}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(4,'welcome_user','ترحيب بمستخدم جديد','email','مرحباً بك في {app_name}!','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>🎉 أهلاً وسهلاً!</h2>\n    <p>مرحباً {name}،</p>\n    <p>نحن سعداء بانضمامك إلينا في {app_name}!</p>\n    <p>يمكنك الآن تسجيل الدخول والبدء في استخدام النظام:</p>\n    <div style=\"text-align: center; margin: 30px 0;\">\n        <a href=\"{login_url}\" style=\"background-color: #4f46e5; color: white; padding: 12px 30px; text-decoration: none; border-radius: 8px; display: inline-block;\">تسجيل الدخول</a>\n    </div>\n    <p>فريق {app_name}</p>\n</div>','[\"{name}\", \"{app_name}\", \"{login_url}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(5,'new_invoice','إشعار فاتورة جديدة','email','فاتورة جديدة #{invoice_number} - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>📄 فاتورة جديدة</h2>\n    <p>مرحباً {name}،</p>\n    <p>تم إنشاء فاتورة جديدة لحسابك:</p>\n    <div style=\"background-color: #f3f4f6; border-radius: 8px; padding: 20px; margin: 20px 0;\">\n        <p><strong>رقم الفاتورة:</strong> {invoice_number}</p>\n        <p><strong>المبلغ:</strong> {amount} ر.س</p>\n        <p><strong>تاريخ الاستحقاق:</strong> {due_date}</p>\n    </div>\n    <p>فريق {app_name}</p>\n</div>','[\"{name}\", \"{app_name}\", \"{invoice_number}\", \"{amount}\", \"{due_date}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(6,'payment_confirmation','تأكيد الدفع','email','تأكيد الدفع - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>✅ تم استلام الدفعة</h2>\n    <p>مرحباً {name}،</p>\n    <p>شكراً لك! تم استلام دفعتك بنجاح.</p>\n    <div style=\"background-color: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 8px; padding: 20px; margin: 20px 0;\">\n        <p><strong>المبلغ:</strong> {amount} ر.س</p>\n        <p><strong>طريقة الدفع:</strong> {payment_method}</p>\n        <p><strong>رقم المرجع:</strong> {reference}</p>\n        <p><strong>التاريخ:</strong> {date}</p>\n    </div>\n    <p>فريق {app_name}</p>\n</div>','[\"{name}\", \"{app_name}\", \"{amount}\", \"{payment_method}\", \"{reference}\", \"{date}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(7,'subscription_expiry','تنبيه انتهاء الاشتراك','email','⚠️ اشتراكك سينتهي قريباً - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>⚠️ تنبيه: اشتراكك سينتهي قريباً</h2>\n    <p>مرحباً {name}،</p>\n    <p>نود تذكيرك بأن اشتراكك سينتهي في <strong>{expiry_date}</strong>.</p>\n    <p>لتجنب انقطاع الخدمة، يرجى تجديد اشتراكك في أقرب وقت.</p>\n    <div style=\"text-align: center; margin: 30px 0;\">\n        <a href=\"{renew_url}\" style=\"background-color: #4f46e5; color: white; padding: 12px 30px; text-decoration: none; border-radius: 8px; display: inline-block;\">تجديد الاشتراك</a>\n    </div>\n    <p>فريق {app_name}</p>\n</div>','[\"{name}\", \"{app_name}\", \"{expiry_date}\", \"{renew_url}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(8,'appointment_reminder','تذكير بموعد','email','🔔 تذكير بموعدك - {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl;\">\n    <h2>🔔 تذكير بموعدك</h2>\n    <p>مرحباً {customer_name}،</p>\n    <p>نود تذكيرك بموعدك القادم:</p>\n    <div style=\"background-color: #eff6ff; border: 1px solid #bfdbfe; border-radius: 8px; padding: 20px; margin: 20px 0;\">\n        <p><strong>التاريخ:</strong> {date}</p>\n        <p><strong>الوقت:</strong> {time}</p>\n        <p><strong>الخدمة:</strong> {service}</p>\n        <p><strong>المركبة:</strong> {vehicle}</p>\n    </div>\n    <p>نتطلع لخدمتكم!</p>\n    <p>فريق {center_name}</p>\n</div>','[\"{customer_name}\", \"{date}\", \"{time}\", \"{service}\", \"{vehicle}\", \"{center_name}\", \"{app_name}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01'),(9,'employee_invitation','دعوة موظف جديد','email','مرحباً بك في الفريق - تفعيل حسابك في {app_name}','<div style=\"font-family: sans-serif; text-align: right; direction: rtl; max-width: 600px; margin: 0 auto; background: #fff; padding: 40px; border-radius: 12px;\">\n    <div style=\"text-align: center; margin-bottom: 30px;\">\n        <div style=\"width: 80px; height: 80px; background: linear-gradient(135deg, #8b5cf6 0%, #6366f1 100%); border-radius: 50%; margin: 0 auto 20px; text-align: center; line-height: 80px;\">\n            <span style=\"font-size: 36px;\">👋</span>\n        </div>\n        <h1 style=\"color: #111827; font-size: 24px; margin: 0;\">مرحباً بك في الفريق!</h1>\n        <p style=\"color: #6b7280; margin: 5px 0 0;\">تم إنشاء حساب لك في النظام</p>\n    </div>\n    \n    <p style=\"color: #374151; font-size: 16px; line-height: 1.8;\">\n        أهلاً <strong>{name}</strong>،\n    </p>\n    <p style=\"color: #374151; font-size: 16px; line-height: 1.8;\">\n        تم إضافتك كموظف في نظام <strong>{app_name}</strong>.\n        يرجى الضغط على الزر أدناه لتفعيل حسابك وتعيين كلمة المرور الخاصة بك.\n    </p>\n    \n    <div style=\"text-align: center; margin: 30px 0;\">\n        <a href=\"{activation_url}\" style=\"display: inline-block; padding: 14px 32px; background: linear-gradient(135deg, #8b5cf6 0%, #6366f1 100%); color: #ffffff; text-decoration: none; border-radius: 10px; font-weight: bold; font-size: 16px;\">تفعيل الحساب وتعيين كلمة المرور</a>\n    </div>\n    \n    <div style=\"background-color: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 8px; padding: 16px; margin: 20px 0; color: #166534;\">\n        ✨ بعد التفعيل ستتمكن من:\n        <ul style=\"margin: 10px 0 0; padding-right: 20px;\">\n            <li>الوصول لبوابة الموظف الذاتية</li>\n            <li>مشاهدة سجل الحضور والإجازات</li>\n            <li>متابعة كشوف الرواتب</li>\n        </ul>\n    </div>\n    \n    <div style=\"background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 8px; padding: 16px; margin: 20px 0; color: #92400e;\">\n        ⚠️ هذا الرابط صالح لمدة <strong>3 أيام</strong> فقط. إذا انتهت صلاحيته، تواصل مع مسؤول الموارد البشرية.\n    </div>\n    \n    <p style=\"text-align: center; color: #9ca3af; font-size: 13px;\">\n        🔒 إذا لم تتوقع هذه الدعوة، يرجى تجاهل هذا البريد.\n    </p>\n    \n    <div style=\"margin-top: 40px; padding-top: 20px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #9ca3af; text-align: center;\">\n        &copy; 2026 {app_name}. جميع الحقوق محفوظة.\n    </div>\n</div>','[\"{name}\", \"{app_name}\", \"{activation_url}\"]',1,'2026-07-08 04:39:01','2026-07-08 04:39:01');
