DROP TABLE IF EXISTS `vehicle_mileage_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicle_mileage_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vehicle_id` bigint unsigned NOT NULL,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `center_id` bigint unsigned DEFAULT NULL,
  `mileage` int unsigned NOT NULL,
  `previous_mileage` int unsigned DEFAULT NULL,
  `difference` int NOT NULL DEFAULT '0',
  `reference_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reference_id` bigint unsigned DEFAULT NULL,
  `reference_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `recorded_at` timestamp NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicle_mileage_logs_reference_type_reference_id_index` (`reference_type`,`reference_id`),
  KEY `vehicle_mileage_logs_created_by_foreign` (`created_by`),
  KEY `vehicle_mileage_logs_vehicle_id_index` (`vehicle_id`),
  KEY `vehicle_mileage_logs_tenant_id_center_id_index` (`tenant_id`,`center_id`),
  KEY `vehicle_mileage_logs_center_id_foreign` (`center_id`),
  CONSTRAINT `vehicle_mileage_logs_center_id_foreign` FOREIGN KEY (`center_id`) REFERENCES `centers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vehicle_mileage_logs_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vehicle_mileage_logs_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vehicle_mileage_logs_vehicle_id_foreign` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
